/* Minimal QR encoder: byte mode, ECC level M, versions 1-10 */
function qrMatrix(text){
  const bytes=[];{const s=unescape(encodeURIComponent(text));for(let i=0;i<s.length;i++)bytes.push(s.charCodeAt(i));}
  const T=[null,[10,[[1,16]]],[16,[[1,28]]],[26,[[1,44]]],[18,[[2,32]]],[24,[[2,43]]],[16,[[4,27]]],[18,[[4,31]]],[22,[[2,38],[2,39]]],[22,[[3,36],[2,37]]],[26,[[4,43],[1,44]]]];
  let v=1,dc=0,ec=0,groups=null;
  for(;v<=10;v++){ec=T[v][0];groups=T[v][1];dc=groups.reduce((a,g)=>a+g[0]*g[1],0);
    if(4+(v<10?8:16)+8*bytes.length<=dc*8)break;}
  if(v>10)return null;
  const bits=[];const put=(val,len)=>{for(let i=len-1;i>=0;i--)bits.push((val>>>i)&1);};
  put(4,4);put(bytes.length,v<10?8:16);bytes.forEach(b=>put(b,8));
  for(let i=0;i<4&&bits.length<dc*8;i++)bits.push(0);
  while(bits.length%8)bits.push(0);
  const data=[];for(let i=0;i<bits.length;i+=8){let b=0;for(let j=0;j<8;j++)b=b<<1|bits[i+j];data.push(b);}
  for(let p=0;data.length<dc;p++)data.push(p%2?0x11:0xEC);
  // Reed-Solomon
  const EXP=new Array(512),LOG=new Array(256);
  for(let i=0,x=1;i<255;i++){EXP[i]=x;LOG[x]=i;x<<=1;if(x&256)x^=0x11d;}
  for(let i=255;i<512;i++)EXP[i]=EXP[i-255];
  const mul=(a,b)=>a&&b?EXP[LOG[a]+LOG[b]]:0;
  let gen=[1];
  for(let i=0;i<ec;i++){const ng=new Array(gen.length+1).fill(0);
    for(let j=0;j<gen.length;j++){ng[j]^=gen[j];ng[j+1]^=mul(gen[j],EXP[i]);}gen=ng;}
  const rs=blk=>{const r=new Array(ec).fill(0);
    for(const b of blk){const f=b^r.shift();r.push(0);for(let i=0;i<ec;i++)r[i]^=mul(gen[i+1],f);}return r;};
  const blocks=[];let pos=0;
  groups.forEach(([n,len])=>{for(let i=0;i<n;i++){const d=data.slice(pos,pos+len);pos+=len;blocks.push({d,e:rs(d)});}});
  const out=[];const maxd=Math.max(...blocks.map(b=>b.d.length));
  for(let i=0;i<maxd;i++)blocks.forEach(b=>{if(i<b.d.length)out.push(b.d[i]);});
  for(let i=0;i<ec;i++)blocks.forEach(b=>out.push(b.e[i]));
  // matrix
  const N=17+4*v;
  const M=Array.from({length:N},()=>new Array(N).fill(false));
  const F=Array.from({length:N},()=>new Array(N).fill(false));
  const setF=(x,y,d)=>{M[y][x]=d;F[y][x]=true;};
  for(let i=0;i<N;i++){setF(6,i,i%2==0);setF(i,6,i%2==0);}
  const finder=(cx,cy)=>{for(let dy=-4;dy<=4;dy++)for(let dx=-4;dx<=4;dx++){
    const x=cx+dx,y=cy+dy;if(x<0||y<0||x>=N||y>=N)continue;
    const d=Math.max(Math.abs(dx),Math.abs(dy));setF(x,y,d!=2&&d!=4);}};
  finder(3,3);finder(N-4,3);finder(3,N-4);
  const na=v==1?0:Math.floor(v/7)+2;
  let ap=[];
  if(na){const step=Math.ceil((v*4+4)/(na*2-2))*2;ap=[6];
    for(let p=N-7,k=0;k<na-1;p-=step,k++)ap.splice(1,0,p);}
  ap.forEach((ax,i)=>ap.forEach((ay,j)=>{
    if((i==0&&j==0)||(i==0&&j==ap.length-1)||(i==ap.length-1&&j==0))return;
    for(let dy=-2;dy<=2;dy++)for(let dx=-2;dx<=2;dx++)setF(ax+dx,ay+dy,Math.max(Math.abs(dx),Math.abs(dy))!=1);}));
  const fmt=mask=>{const d=mask;let r=d;for(let i=0;i<10;i++)r=(r<<1)^((r>>>9)*0x537);
    const b=((d<<10)|r)^0x5412,g=i=>((b>>>i)&1)!=0;
    for(let i=0;i<=5;i++)setF(8,i,g(i));setF(8,7,g(6));setF(8,8,g(7));setF(7,8,g(8));
    for(let i=9;i<15;i++)setF(14-i,8,g(i));
    for(let i=0;i<8;i++)setF(N-1-i,8,g(i));
    for(let i=8;i<15;i++)setF(8,N-15+i,g(i));
    setF(8,N-8,true);};
  fmt(0);
  if(v>=7){let r=v;for(let i=0;i<12;i++)r=(r<<1)^((r>>>11)*0x1F25);
    const b=(v<<12)|r;for(let i=0;i<18;i++){const bit=((b>>>i)&1)!=0,a=N-11+i%3,c=Math.floor(i/3);setF(a,c,bit);setF(c,a,bit);}}
  let k=0;const total=out.length*8;
  for(let right=N-1;right>=1;right-=2){if(right==6)right=5;
    for(let vert=0;vert<N;vert++)for(let j=0;j<2;j++){
      const x=right-j,up=((right+1)&2)==0,y=up?N-1-vert:vert;
      if(!F[y][x]&&k<total){M[y][x]=((out[k>>>3]>>>(7-(k&7)))&1)!=0;k++;}}}
  const mf=[(x,y)=>(x+y)%2==0,(x,y)=>y%2==0,(x,y)=>x%3==0,(x,y)=>(x+y)%3==0,
    (x,y)=>(Math.floor(x/3)+Math.floor(y/2))%2==0,(x,y)=>x*y%2+x*y%3==0,
    (x,y)=>(x*y%2+x*y%3)%2==0,(x,y)=>((x+y)%2+x*y%3)%2==0];
  const penalty=G=>{let p=0;
    for(let t=0;t<2;t++){for(let a=0;a<N;a++){let run=1;
      for(let b=1;b<N;b++){const c=t?G[b][a]:G[a][b],q=t?G[b-1][a]:G[a][b-1];
        if(c==q){run++;if(run==5)p+=3;else if(run>5)p++;}else run=1;}
      for(let b=0;b+10<N;b++){const s=[];for(let i=0;i<11;i++)s.push((t?G[b+i][a]:G[a][b+i])?1:0);
        const j=s.join('');if(j=='10111010000'||j=='00001011101')p+=40;}}}
    for(let y=0;y<N-1;y++)for(let x=0;x<N-1;x++){const c=G[y][x];
      if(c==G[y][x+1]&&c==G[y+1][x]&&c==G[y+1][x+1])p+=3;}
    let dark=0;G.forEach(r=>r.forEach(c=>{if(c)dark++;}));
    p+=Math.floor(Math.abs(dark*20-N*N*10)/(N*N))*10;return p;};
  let best=null,bm=0,bp=1e9;
  for(let m=0;m<8;m++){
    const G=M.map((r,y)=>r.map((c,x)=>F[y][x]?c:(c!=mf[m](x,y))));
    // apply format bits for this mask on copy
    const save=M.map(r=>r.slice());
    for(let y=0;y<N;y++)for(let x=0;x<N;x++)M[y][x]=G[y][x];
    fmt(m);const G2=M.map(r=>r.slice());
    for(let y=0;y<N;y++)for(let x=0;x<N;x++)M[y][x]=save[y][x];
    const p=penalty(G2);if(p<bp){bp=p;best=G2;bm=m;}}
  return best;
}
function qrDraw(canvas,text,size){
  const G=qrMatrix(text);if(!G)return false;
  const n=G.length,q=4,sc=Math.floor(size/(n+q*2))||1,px=(n+q*2)*sc;
  canvas.width=canvas.height=px;const c=canvas.getContext('2d');
  c.fillStyle='#fff';c.fillRect(0,0,px,px);c.fillStyle='#000';
  for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(G[y][x])c.fillRect((x+q)*sc,(y+q)*sc,sc,sc);
  return true;
}

/* ===== Telecom Offers app (v3) ===== */
var CFG=window.CFG||{};
CFG.dataUrl=CFG.dataUrl||"data/offers.json";
if(CFG.logoDir===undefined)CFG.logoDir="logos/";
CFG.apiUrl=CFG.apiUrl||"";
CFG.near=CFG.near===undefined?3:CFG.near;
CFG.contact=CFG.contact||{};
const CONTACT=CFG.contact;
const LANGS=[["ar","العربية","AR"],["en","English","EN"],["ur","اردو","UR"],["bn","বাংলা","BN"],["hi","हिन्दी","HI"],["am","አማርኛ","AM"]];
const RTL={ar:1,ur:1};
const CATS=["cd","fx","dt","vz"];
let CO=[],BASE=null;
const ALL=[];
const ADMIN={on:false,pin:"",edit:""};

/* ---------- state ---------- */
const KEY="telecom_offers_v1",LKEY="toff_local_v1",CACHE_KEY="toff_data_v3";
let S={lang:null,theme:"auto",favs:[],cmp:[],name:"",exAct:"share"};
try{const x=JSON.parse(localStorage.getItem(KEY)||"null");if(x)S=Object.assign(S,x);}catch(e){}
if(!S.lang){const n=(navigator.language||"ar").slice(0,2);S.lang=LANGS.some(l=>l[0]===n)?n:"ar";}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S));}catch(e){}};
let L={edits:{},adds:[],costs:{},log:[]};
try{const x=JSON.parse(localStorage.getItem(LKEY)||"null");if(x)L=Object.assign(L,x);}catch(e){}
const saveL=()=>{try{localStorage.setItem(LKEY,JSON.stringify(L));}catch(e){}};
const t=k=>(T[S.lang]&&T[S.lang][k])||T.en[k]||k;
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const coName=c=>c.n[S.lang]||c.n.en;
const ctryName=n=>(CTRY[S.lang]&&CTRY[S.lang][n])||n;

/* ---------- icon ---------- */
function iconSVG(){
  const arc=r=>{const d=r*.7071;return `<path d="M${256-d} ${330-d}A${r} ${r} 0 0 1 ${256+d} ${330-d}" fill="none" stroke="#fff" stroke-width="34" stroke-linecap="round"/>`;};
  return `<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#0f766e"/><stop offset="1" stop-color="#14b8a6"/></linearGradient></defs><rect width="512" height="512" rx="112" fill="url(#g)"/>${arc(70)}${arc(130)}${arc(190)}<circle cx="256" cy="330" r="28" fill="#fff"/><rect x="170" y="392" width="172" height="30" rx="15" fill="#fff" opacity=".9"/></svg>`;
}
$("#logo").innerHTML=iconSVG().replace('id="g"','id="g2"').replace('url(#g)','url(#g2)');

/* ---------- formatting (plain text where possible) ---------- */
const tbNum=d=>{const m=String(d).match(/^(\d+(?:\.\d+)?)TB$/);return m?+m[1]:null;};
function fmtData(d){if(d===""||d===0||d==null)return"";if(d==="U")return t("unl");const tb=tbNum(d);if(tb!==null)return tb+" "+t("tb");return d+" "+t("gb");}
function fmtSocial(s){if(s===""||s===0||s==null)return"";s=String(s);
  if(s==="U")return t("unl");if(s==="Uc")return t("uc");if(s==="Us")return t("usx");
  if(/^\d+(\.\d+)?$/.test(s))return s+" "+t("gb");return s;}
function fmtCalls(c){if(c===""||c==null)return"";const m=String(c).match(/^(U|\d+)([aoilv]?)(?:\+(\d+))?$/);if(!m)return String(c);
  let s=(m[1]==="U"?t("unl"):m[1]+" "+t("min"));
  if(m[2]==="v")s+=" "+t("sc_v");else if(m[2])s+=" · "+t("sc_"+m[2]);
  if(m[3])s+=" + "+m[3]+" "+t("min")+" "+t("sc_a");
  return s;}
function fmtVal(v){if(!v)return"";const n=parseInt(v),u={d:0,w:2,m:4}[v.slice(-1)];return n+" "+t("u")[u+(n===1?0:1)];}
const money=n=>n+" "+t("cur");
function dataNum(d){if(d==="U")return 99999;const tb=tbNum(d);if(tb!==null)return tb*1000;return +d||0;}
function callsNum(c){const m=String(c).match(/^(U|\d+)/);return m?(m[1]==="U"?99999:+m[1]):0;}
function offerTitle(o){return o.n||(o.d==="U"?t("unl"):fmtData(o.d));}
const showOfficial=o=>ADMIN.on||(o.o-o.p>CFG.near);
const priceOf=o=>o.p;

/* ---------- data model ---------- */
function mkItem(cid,cat,r){
  const ap=r[8],ct=r[9],k=r[10];
  return {id:r[0],cid:cid,cat:cat,n:r[1]||"",c:String(r[2]==null?"":r[2]),d:r[3]==null?"":r[3],s:r[4]==null?"":r[4],o:+r[5],p:+r[6],v:r[7]||"",
    apps:ap?String(ap).split(";").filter(Boolean):[],
    ctry:Array.isArray(ct)?ct:(ct?String(ct).split(";").filter(Boolean):[]),
    k:(k===undefined||k===null||k==="")?null:+k};
}
const byId=id=>CO.find(c=>c.id===id);
const isFav=k=>S.favs.indexOf(k)>-1;
function rebuild(){
  if(!BASE)return;
  CO=BASE.companies;ALL.length=0;
  CO.forEach(function(c){CATS.forEach(function(cat){(c.cats[cat]||[]).forEach(function(r){
    ALL.push(mkItem(c.id,cat,L.edits[r[0]]||r));});});});
  L.adds.forEach(function(a){if(byId(a.co))ALL.push(mkItem(a.co,a.cat,a.row));});
  ALL.forEach(function(o){
    if(!ADMIN.on)o.k=null;
    else if(L.costs[o.id]!==undefined&&o.k===null)o.k=+L.costs[o.id];});
}
function stripCost(obj){
  return {rev:obj.rev,updated:obj.updated,companies:obj.companies.map(function(c){
    const cats={};Object.keys(c.cats).forEach(function(k){cats[k]=c.cats[k].map(function(r){return r.slice(0,10);});});
    return Object.assign({},c,{cats:cats});})};
}
let DATA_INFO={src:"",updated:"",ver:""};
function setData(obj,info){BASE=obj;DATA_INFO=info||{src:"json",updated:obj.updated||"",ver:String(obj.rev||obj.updated||"0")};rebuild();}

/* ---------- network ---------- */
function xhr(url,cb){
  try{const x=new XMLHttpRequest();x.open("GET",url);x.timeout=20000;
    x.onreadystatechange=function(){if(x.readyState!==4)return;
      if((x.status>=200&&x.status<300)&&x.responseText)cb(null,x.responseText);else cb(new Error("http "+x.status));};
    x.ontimeout=function(){cb(new Error("timeout"));};x.send();}catch(e){cb(e);}
}
const qs=o=>Object.keys(o).map(k=>encodeURIComponent(k)+"="+encodeURIComponent(o[k])).join("&");
function apiGet(p,cb){
  const u=CFG.apiUrl+(CFG.apiUrl.indexOf("?")>-1?"&":"?")+qs(p)+"&_="+Date.now();
  xhr(u,function(e,txt){if(e)return cb(e);let j;try{j=JSON.parse(txt);}catch(x){return cb(x);}cb(null,j);});
}
function apiPost(body,cb){
  try{const x=new XMLHttpRequest();x.open("POST",CFG.apiUrl);x.timeout=30000;
    x.setRequestHeader("Content-Type","text/plain;charset=utf-8");
    x.onreadystatechange=function(){if(x.readyState!==4)return;
      let j=null;try{j=JSON.parse(x.responseText);}catch(e){}
      if(j)cb(null,j);else cb(new Error("http "+x.status));};
    x.ontimeout=function(){cb(new Error("timeout"));};
    x.send(JSON.stringify(body));}catch(e){cb(e);}
}
function parseCSV(txt){
  const rows=[];let row=[],f="",q=false;
  for(let i=0;i<txt.length;i++){const ch=txt[i];
    if(q){if(ch==='"'){if(txt[i+1]==='"'){f+='"';i++;}else q=false;}else f+=ch;}
    else if(ch==='"')q=true;
    else if(ch===","){row.push(f);f="";}
    else if(ch==="\n"||ch==="\r"){if(ch==="\r"&&txt[i+1]==="\n")i++;row.push(f);f="";if(row.length>1||row[0]!=="")rows.push(row);row=[];}
    else f+=ch;}
  if(f!==""||row.length){row.push(f);rows.push(row);}
  return rows;
}
const numOrStr=x=>{x=(x==null?"":String(x)).trim();return /^\d+(\.\d+)?$/.test(x)?+x:x;};
function apiRowToArr(r){
  return [String(r.id),r.name==null?"":String(r.name),r.calls==null?"":String(r.calls),numOrStr(r.data),numOrStr(r.social),+r.official,+r.price,
    r.validity==null?"":String(r.validity),r.apps==null?"":String(r.apps),r.countries?String(r.countries).split(";").filter(Boolean):[],
    (r.cost===undefined||r.cost===""||r.cost===null)?"":+r.cost];
}
function composeFromApi(base,j){
  const map={};base.companies.forEach(function(c){map[c.id]={};});let n=0;
  (j.rows||[]).forEach(function(r){const cid=String(r.company||"").trim(),cat=String(r.category||"").trim();
    if(!map[cid]||CATS.indexOf(cat)<0||isNaN(+r.official)||isNaN(+r.price))return;
    (map[cid][cat]=map[cid][cat]||[]).push(apiRowToArr(r));n++;});
  if(!n)return null;
  return {rev:j.version,updated:String(j.version||"").slice(0,10),companies:base.companies.map(function(c){return Object.assign({},c,{cats:map[c.id]});}).filter(function(c){return Object.keys(c.cats).length;})};
}
function readCache(){try{const c=JSON.parse(localStorage.getItem(CACHE_KEY)||"null");return c&&c.obj&&c.obj.companies?c:null;}catch(e){return null;}}
function writeCache(obj,info){try{localStorage.setItem(CACHE_KEY,JSON.stringify({obj:stripCost(obj),info:info}));}catch(e){}}
let PENDING=null;
function applyFresh(obj,info,manual){
  setData(obj,info);writeCache(obj,info);route();if(manual)toast(t("refreshed"));
}
function loadData(manual){
  const cached=manual?null:readCache();
  if(cached){setData(cached.obj,cached.info);route();}
  else if(!manual)$("#view").innerHTML=`<div class="empty">${t("loading")}</div>`;
  const q=u=>u+(u.indexOf("?")>-1?"&":"?")+"_="+Date.now();
  xhr(q(CFG.dataUrl),function(err,txt){
    let base=null;try{base=JSON.parse(txt);}catch(e){}
    if(err||!base||!base.companies){if(!BASE)errScreen();else if(manual)toast(t("load_err"));return;}
    const fin=function(obj,info){
      const changed=cached&&cached.info&&cached.info.ver!==info.ver;
      if(changed&&!manual&&!ADMIN.on){PENDING={obj:obj,info:info};showUpdateModal("data");}
      else applyFresh(obj,info,manual);
    };
    if(CFG.apiUrl){
      const p={action:"offers"};if(ADMIN.on)p.pin=ADMIN.pin;
      apiGet(p,function(e2,j){
        const o=!e2&&j&&j.ok&&composeFromApi(base,j);
        if(o)fin(o,{src:"api",updated:String(j.version||"").slice(0,10),ver:String(j.version)});
        else fin(base,{src:"json",updated:base.updated||"",ver:String(base.rev||base.updated||"0")});});
    }else fin(base,{src:"json",updated:base.updated||"",ver:String(base.rev||base.updated||"0")});
  });
}
function errScreen(){$("#view").innerHTML=`<div class="empty">⚠️<br>${t("load_err")}<br><br><button class="btn" data-act="retry">${t("retry")}</button></div>`;}

/* ---------- view state ---------- */
let VS={hv:"",htol:"10",hcat:"all",hsort:"c",hctry:"",pcat:"all",psort:"c",pctry:"",cmode:"price",pv:"",tol:"10",cid:"",ccat:"all",csort:"n",cctry:"",cc:"",sq:"",smax:"",ssort:"o"};
let LASTLIST=[];
const tile=(c,cls)=>{const src=CFG.logoDir?CFG.logoDir+c.id+".png":"";return `<div class="ic ${src?"lg ":""}${cls||""}" style="background:linear-gradient(135deg,${c.c},${c.c}cc)"><span>${c.l}</span>${src?`<img src="${src}" alt="" onerror="this.parentNode.removeChild(this)">`:""}</div>`;};
const catsOf=cid=>CATS.filter(k=>ALL.some(o=>o.cid===cid&&o.cat===k));
const getById=id=>ALL.find(o=>o.id===id);
function ctryList(){const s={};ALL.forEach(o=>{if(o.cat==="fx")o.ctry.forEach(c=>{s[c]=1;});});return Object.keys(s).sort((a,b)=>ctryName(a).localeCompare(ctryName(b),S.lang));}
const passCtry=(o,cat,ct)=>!(cat==="fx"&&ct)||(o.cat==="fx"&&(o.ctry.length===0||o.ctry.indexOf(ct)>-1));

/* ---------- card ---------- */
function offerCard(o,showCo){
  const c=byId(o.cid),calls=fmtCalls(o.c),soc=fmtSocial(o.s),dat=fmtData(o.d),val=fmtVal(o.v);
  const chips=[calls&&`<span>📞 <b>${t("calls")}:</b> ${esc(calls)}</span>`,dat&&`<span>📶 <b>${t("data")}:</b> ${esc(dat)}</span>`,soc&&`<span>💬 <b>${t("social")}:</b> ${esc(soc)}</span>`].filter(Boolean).join("");
  const price=`<div class="pr">${showOfficial(o)?`<div><span>${t("official")}</span><b>${money(o.o)}</b></div>`:""}<div class="c"><span>${t("offerp")}</span><b>${money(o.p)}</b></div>${ADMIN.on?`<div class="k"><span>${t("cost")}</span><b>${o.k==null?"–":money(o.k)}</b></div>`:""}</div>`;
  const apps=o.apps.length?`<div class="det">🧩 <b>${t("apps_incl")}:</b> ${esc(o.apps.join(", "))}</div>`:"";
  const ctr=(o.cat==="fx"||o.cat==="vz")&&o.ctry.length?`<details class="det"><summary>🌍 <b>${t("countries")}</b> (${o.ctry.length})</summary><div>${o.ctry.map(x=>esc(ctryName(x))).join(" · ")}</div></details>`:"";
  const id=esc(o.id);
  return `<div class="offer wm"><div class="oh">${showCo?tile(c,"sm"):""}<div class="t"><b>${esc(offerTitle(o))}</b><small>${showCo?esc(coName(c))+" · ":""}${t("cat_"+o.cat)}${val?" · 🕒 "+val:""}</small></div><button class="star ${isFav(o.id)?"on":""}" data-act="fav" data-k="${id}" aria-label="save">${isFav(o.id)?"★":"☆"}</button></div>${chips?`<div class="fx">${chips}</div>`:""}${apps}${ctr}${price}<div class="acts2"><button class="w" data-act="wa" data-k="${id}">${t("wa_share")}</button><button class="${S.cmp.indexOf(o.id)>-1?"on":""}" data-act="cmp" data-k="${id}">⚖ ${t("cmp")}</button>${ADMIN.on?`<button class="ed" data-act="edit" data-k="${id}">✏️ ${t("edit")}</button>`:""}</div></div>`;
}
function sortList(a,mode){a=a.slice();if(mode==="o")a.sort((x,y)=>x.p-y.p||dataNum(y.d)-dataNum(x.d));else if(mode==="d")a.sort((x,y)=>dataNum(y.d)-dataNum(x.d)||x.p-y.p);return a;}

/* ---------- filters (shared by company / home finder / compare) ---------- */
function filtUI(p,cats,sorts){
  const cur=VS[p+"cat"],sv=VS[p+"sort"],ct=VS[p+"ctry"];
  let h=`<div class="chips">${["all"].concat(cats).map(k=>`<button class="chip ${cur===k?"on":""}" data-act="fcat" data-p="${p}" data-v="${k}">${t("cat_"+k)}</button>`).join("")}</div><div class="tools">`;
  if(cur==="fx")h+=`<select data-act="fctry" data-p="${p}"><option value="">🌍 ${t("all_countries")}</option>${ctryList().map(c=>`<option value="${esc(c)}" ${ct===c?"selected":""}>${esc(ctryName(c))}</option>`).join("")}</select>`;
  h+=`<select data-act="fsort" data-p="${p}">${sorts.map(x=>`<option value="${x}" ${sv===x?"selected":""}>${t("s_"+x)}</option>`).join("")}</select></div>`;
  return h;
}
const SORT_F=["c","o","d"],SORT_C=["n","o","d"];
function finderList(v,tol,cat,ctry,sort){
  const l=ALL.filter(o=>(cat==="all"||o.cat===cat)&&passCtry(o,cat,ctry)&&Math.abs(o.p-v)<=tol);
  l.sort(function(x,y){
    if(sort==="o")return x.p-y.p||dataNum(y.d)-dataNum(x.d);
    if(sort==="d")return dataNum(y.d)-dataNum(x.d)||x.p-y.p;
    return Math.abs(x.p-v)-Math.abs(y.p-v)||dataNum(y.d)-dataNum(x.d);});
  return l.slice(0,40);
}
const exB=(scope,cls)=>ADMIN.on?`<button ${cls?`class="${cls}" `:""}data-act="ex" data-scope="${scope}">🖨 ${t("print_btn")}</button>`:"";

/* ---------- home ---------- */
function homeBody(){
  const v=parseFloat(VS.hv);
  if(!(v>0))return `<div class="grid">${CO.map(c=>{const n=ALL.filter(o=>o.cid===c.id).length;return `<div class="co" data-act="open" data-id="${c.id}">${tile(c)}<b>${esc(coName(c))}</b><small>${n} ${t("offers")}</small></div>`;}).join("")}</div>`;
  const l=finderList(v,+VS.htol,VS.hcat,VS.hctry,VS.hsort),F=filtUI("h",["cd","fx","dt","vz"],SORT_F);
  LASTLIST=l.map(o=>o.id);
  if(!l.length)return F+`<div class="empty">${t("nores")}</div>`;
  return F+`<p class="sub">${l.length} ${t("offers")} ${t("near")} ${v} ${t("cur")}</p>${l.map(o=>offerCard(o,true)).join("")}<div class="acts2"><button class="on" data-act="cmpthese">⚖ ${t("cmp_these")}</button>${exB("list")}</div>`;
}
function vHome(){
  return `<div class="sec" style="padding:12px 14px"><b>${t("need_price")}</b><div class="tools" style="margin:8px 0 0"><input id="hpv" type="number" inputmode="decimal" placeholder="0" value="${esc(VS.hv)}"><select id="htol">${[["0",t("tol_exact")],["10","± 10"],["20","± 20"],["30","± 30"]].map(x=>`<option value="${x[0]}" ${VS.htol===x[0]?"selected":""}>${x[1]}</option>`).join("")}</select></div></div><div id="hbody">${homeBody()}</div>`;
}

/* ---------- company ---------- */
function companyBody(){
  const c=byId(VS.cid);if(!c)return "";
  if(VS.ccat!=="all"&&catsOf(c.id).indexOf(VS.ccat)<0)VS.ccat="all";
  const l=sortList(ALL.filter(o=>o.cid===c.id&&(VS.ccat==="all"||o.cat===VS.ccat)&&passCtry(o,VS.ccat,VS.cctry)),VS.csort);
  const note=c.notes&&(c.notes[S.lang]||c.notes.en);
  return filtUI("c",catsOf(c.id),SORT_C)+(l.length?l.map(o=>offerCard(o)).join(""):`<div class="empty">${t("nores")}</div>`)+(note?`<div class="note">${esc(note)}</div>`:"");
}
function vCompany(id){
  const c=byId(id);if(!c)return vHome();
  VS.cid=id;
  return `<div class="bar"><button class="back" data-act="home">${RTL[S.lang]?"→":"←"}</button>${tile(c,"sm")}<h2 style="flex:1">${esc(coName(c))}</h2>${ADMIN.on?`<button class="hb" data-act="ex" data-scope="co:${c.id}" aria-label="print">🖨</button>`:""}</div><div id="cbody">${companyBody()}</div>`;
}

/* ---------- search / favorites ---------- */
function searchList(){
  let l=ALL.filter(o=>{const c=byId(o.cid),q=VS.sq.trim().toLowerCase();
    if(q){const hay=(coName(c)+" "+c.n.en+" "+offerTitle(o)+" "+o.d+" "+o.p+" "+o.o).toLowerCase();if(hay.indexOf(q)<0)return false;}
    if(VS.smax!==""&&o.p>+VS.smax)return false;return true;});
  l=sortList(l,VS.ssort);
  return l.length?l.map(o=>offerCard(o,true)).join(""):`<div class="empty">${t("nores")}</div>`;
}
function vSearch(){
  return `<h2>${t("search")}</h2><div class="tools"><input id="sq" type="search" placeholder="${t("sph")}" value="${esc(VS.sq)}"><input id="smax" type="number" inputmode="numeric" placeholder="${t("budget")}" value="${esc(VS.smax)}" style="max-width:130px"><select id="ssort"><option value="o" ${VS.ssort==="o"?"selected":""}>${t("s_o")}</option><option value="d" ${VS.ssort==="d"?"selected":""}>${t("s_d")}</option></select></div><div id="slist">${searchList()}</div>`;
}
function vFavs(){
  const l=ALL.filter(o=>isFav(o.id));
  return `<h2>${t("favs")}</h2>${l.length?l.map(o=>offerCard(o,true)).join(""):`<div class="empty">☆<br>${t("fav_empty")}</div>`}`;
}

/* ---------- compare ---------- */
function priceResults(){
  const v=parseFloat(VS.pv),F=filtUI("p",["cd","fx","dt","vz"],SORT_F);
  if(!(v>0))return F+`<div class="empty">💰<br>${t("price_ph")}</div>`;
  const l=finderList(v,+VS.tol,VS.pcat,VS.pctry,VS.psort);LASTLIST=l.map(o=>o.id);
  if(!l.length)return F+`<div class="empty">${t("nores")}</div>`;
  const pg=o=>{const d=dataNum(o.d);return d&&d<1000?o.p/d:null;};
  const mx=fn=>Math.max.apply(null,l.map(fn)),mn=fn=>{const x=l.map(fn).filter(z=>z);return x.length?Math.min.apply(null,x):null;};
  const bd=mx(o=>dataNum(o.d)),bc=mx(o=>callsNum(o.c)),bg=mn(pg),multi=l.length>1;
  const rows=l.map(o=>{const c=byId(o.cid),g=pg(o);return `<tr><td>${tile(c,"sm")}<b>${esc(coName(c))}</b><br><small>${esc(offerTitle(o))}</small></td>
   <td class="${multi&&callsNum(o.c)===bc?"best":""}">${esc(fmtCalls(o.c))||"–"}</td><td class="${multi&&dataNum(o.d)===bd?"best":""}">${esc(fmtData(o.d))||"–"}</td><td>${esc(fmtSocial(o.s))||"–"}</td><td>${fmtVal(o.v)||"–"}</td>${ADMIN.on||l.some(showOfficial)?`<td>${showOfficial(o)?money(o.o):"–"}</td>`:""}<td><b>${money(o.p)}</b></td>${ADMIN.on?`<td>${o.k==null?"–":money(o.k)}</td>`:""}<td class="${multi&&g&&bg!=null&&Math.abs(g-bg)<1e-9?"best":""}">${g?g.toFixed(2)+" "+t("cur"):"–"}</td></tr>`;}).join("");
  const offCol=ADMIN.on||l.some(showOfficial);
  return F+`<p class="sub">${l.length} ${t("offers")} ${t("near")} ${v} ${t("cur")}</p><div class="cmpw wm"><table class="cmp"><tr><th>${t("pick_pk")}</th><th>${t("calls")}</th><th>${t("data")}</th><th>${t("social")}</th><th>${t("valid")}</th>${offCol?`<th>${t("official")}</th>`:""}<th>${t("offerp")}</th>${ADMIN.on?`<th>${t("cost")}</th>`:""}<th>${t("pergb")}</th></tr>${rows}</table></div><p class="sub" style="margin-top:8px">${t("cmp_hint")}</p>${ADMIN.on?`<div class="acts2">${exB("list")}</div>`:""}`;
}
function vPrice(){
  return `<div class="tools"><input id="pv" type="number" inputmode="decimal" placeholder="${t("price_ph")}" value="${esc(VS.pv)}"><select id="ptol">${[["0",t("tol_exact")],["10","± 10"],["20","± 20"],["30","± 30"]].map(x=>`<option value="${x[0]}" ${VS.tol===x[0]?"selected":""}>${x[1]}</option>`).join("")}</select></div><div id="pres">${priceResults()}</div>`;
}
function vManual(){
  const sel=S.cmp.map(getById).filter(Boolean);
  if(!VS.cc||!byId(VS.cc))VS.cc=CO.length?CO[0].id:"";
  const pk=ALL.filter(o=>o.cid===VS.cc);
  const pick=`<div class="tools"><select data-act="cco">${CO.map(c=>`<option value="${c.id}" ${c.id===VS.cc?"selected":""}>${esc(coName(c))}</option>`).join("")}</select><select id="cpk">${pk.map(o=>`<option value="${esc(o.id)}">${esc(offerTitle(o))} · ${esc(fmtData(o.d))} · ${o.p}</option>`).join("")}</select><button class="btn" data-act="cmpadd" style="flex:none">${t("add")}</button></div>`;
  if(!sel.length)return `${pick}<div class="empty">⚖<br>${t("cmp_empty")}</div>`;
  const pg=o=>{const d=dataNum(o.d);return d&&d<1000?o.p/d:null;};
  const best=(fn,dir)=>{const v=sel.map(fn).filter(x=>x!=null&&x>0);return v.length>1?(dir>0?Math.max.apply(null,v):Math.min.apply(null,v)):null;};
  const bp=best(o=>o.p,-1),bd=best(o=>dataNum(o.d),1),bc=best(o=>callsNum(o.c),1),bg=best(pg,-1);
  const row=(lab,fn,cls)=>`<tr><td>${lab}</td>${sel.map(o=>`<td class="${cls?cls(o):""}">${fn(o)||"–"}</td>`).join("")}</tr>`;
  return `${pick}<div class="cmpw wm"><table class="cmp"><tr><th></th>${sel.map(o=>{const c=byId(o.cid);return `<th>${tile(c,"sm")}${esc(coName(c))}<br><small>${esc(offerTitle(o))}</small><br><button class="rm" data-act="cmp" data-k="${esc(o.id)}">✕</button></th>`;}).join("")}</tr>
  ${row(t("calls"),o=>esc(fmtCalls(o.c)),o=>bc!=null&&callsNum(o.c)===bc?"best":"")}
  ${row(t("data"),o=>esc(fmtData(o.d)),o=>bd!=null&&dataNum(o.d)===bd?"best":"")}
  ${row(t("social"),o=>esc(fmtSocial(o.s)))}
  ${row(t("apps_incl"),o=>esc(o.apps.join(", ")))}
  ${row(t("valid"),o=>fmtVal(o.v))}
  ${row(t("official"),o=>showOfficial(o)?money(o.o):"")}
  ${row(t("offerp"),o=>money(o.p),o=>bp!=null&&o.p===bp?"best":"")}
  ${ADMIN.on?row(t("cost"),o=>o.k==null?"":money(o.k)):""}
  ${row(t("pergb"),o=>{const g=pg(o);return g?g.toFixed(2)+" "+t("cur"):"";},o=>{const g=pg(o);return bg!=null&&g&&Math.abs(g-bg)<1e-9?"best":"";})}
  </table></div><p class="sub" style="margin-top:8px">${t("cmp_hint")}</p><div class="acts2"><button data-act="cmpclear">${t("cmp_clear")}</button></div>`;
}
function vCompare(){
  const m=VS.cmode==="manual";
  return `<h2>${t("cmp")}</h2><div class="chips"><button class="chip ${m?"":"on"}" data-act="cmode" data-v="price">${t("cmp_byprice")}</button><button class="chip ${m?"on":""}" data-act="cmode" data-v="manual">${t("cmp_manual")}</button></div>${m?vManual():vPrice()}`;
}

