  $("#nav").innerHTML=[["home","🏠",t("home")],["search","🔍",t("search")],["compare","⚖️",t("cmp")],["settings","⚙️",t("settings")]].map(x=>`<button class="${tab===x[0]?"on":""}" data-act="nav" data-v="${x[0]}"><i>${x[1]}</i>${x[2]}</button>`).join("");
