    S.favs=Array.isArray(x.favs)?x.favs.filter(k=>ALL.some(o=>o.id===k)):[];S.cmp=Array.isArray(x.cmp)?x.cmp.filter(k=>ALL.some(o=>o.id===k)).slice(0,4):[];
