/* ---------- updates ---------- */
const newer=(a,b)=>{const x=a.split(".").map(Number),y=b.split(".").map(Number);for(let i=0;i<3;i++){if((x[i]||0)>(y[i]||0))return true;if((x[i]||0)<(y[i]||0))return false;}return false;};
let latest=null;
function showUpdateModal(kind){
  if($("#ov")){if(kind==="data"&&PENDING){applyFresh(PENDING.obj,PENDING.info,false);PENDING=null;}return;}
  modal(`<h3>🔄</h3><div class="ug">${LANGS.map(l=>`<button class="btn" lang="${l[0]}" data-act="updgo" data-v="${l[0]}" data-kind="${kind}"><span>${UPD[l[0]]}</span><small>${l[2]}</small></button>`).join("")}</div>`,"",true);
}
function checkUpdate(manual){
  const btn=$("#chkBtn");if(manual&&btn)btn.textContent=t("checking");
  const fin=function(){if(manual&&$("#chkBtn"))$("#chkBtn").textContent=t("update");};
  try{const x=new XMLHttpRequest();
    x.open("GET",cleanUrl()+"?_="+Date.now());
    x.onreadystatechange=function(){if(x.readyState!==4)return;
      const m=(x.responseText||"").match(/APP_VERSION\s*=\s*"([\d.]+)"/);
      if(m&&newer(m[1],APP_VERSION)){latest=m[1];showUpdateModal("app");}
      else if(manual)toast(t("uptodate"));
      fin();};
    x.send();}
  catch(e){if(manual)toast(t("uptodate"));fin();}
}
function applyUpdate(){
  const go2=function(){location.replace(cleanUrl()+"?v="+(latest||Date.now())+location.hash);};
  const tasks=[];
  try{if("serviceWorker"in navigator)tasks.push(navigator.serviceWorker.getRegistrations().then(function(rs){return Promise.all(rs.map(function(r){return r.unregister();}));}));
    if(window.caches)tasks.push(caches.keys().then(function(ks){return Promise.all(ks.map(function(k){return caches.delete(k);}));}));}catch(e){}
  Promise.all(tasks).then(go2,go2);
}

/* ---------- events ---------- */
let VTAPS=0,VT=0;
document.addEventListener("click",function(e){
  const el=e.target.closest("[data-act]");if(!el)return;const a=el.dataset.act,v=el.dataset.v,p=el.dataset.p;
  if(a==="home")go("home");
  else if(a==="nav")go(v);
  else if(a==="open"){VS.ccat="all";VS.csort="n";VS.cctry="";go("c/"+el.dataset.id);}
  else if(a==="fcat"){VS[p+"cat"]=v;rerender(p);}
  else if(a==="fav"){const k=el.dataset.k,i=S.favs.indexOf(k);if(i<0)S.favs.push(k);else S.favs.splice(i,1);save();
    if(location.hash==="#favs")route();else{el.classList.toggle("on",i<0);el.textContent=i<0?"★":"☆";}}
  else if(a==="theme"){S.theme=v;save();applyTheme();route();}
  else if(a==="exact"){S.exAct=v;save();route();}
  else if(a==="setlang"){S.lang=v;save();closeModal();applyLang();route();}
  else if(a==="favsGo")go("favs");
  else if(a==="wa"){const o=getById(el.dataset.k);if(o)openWA(o);}
  else if(a==="cmp"){const k=el.dataset.k,i=S.cmp.indexOf(k);
    if(i>=0)S.cmp.splice(i,1);else if(S.cmp.length>=4){toast(t("cmp_max"));return;}else S.cmp.push(k);
    save();if(location.hash.slice(1)==="compare")route();else el.classList.toggle("on",i<0);}
  else if(a==="cmpadd"){const k=$("#cpk")&&$("#cpk").value;if(k&&S.cmp.indexOf(k)<0){if(S.cmp.length>=4){toast(t("cmp_max"));return;}S.cmp.push(k);save();route();}}
  else if(a==="cmpclear"){S.cmp=[];save();route();}
  else if(a==="cmode"){VS.cmode=v;route();}
  else if(a==="cmpthese"){VS.pv=VS.hv;VS.tol=VS.htol;VS.pcat=VS.hcat;VS.psort=VS.hsort;VS.pctry=VS.hctry;VS.cmode="price";go("compare");}
  else if(a==="qr")showQR();
  else if(a==="share")shareApp();
  else if(a==="install")doInstall();
  else if(a==="copy")copyText($("#qrurl")?$("#qrurl").value:cleanUrl());
  else if(a==="close")closeModal();
  else if(a==="export")exportBackup();
  else if(a==="import")$("#impFile").click();
  else if(a==="page")go("p/"+v);
  else if(a==="settingsGo")go("settings");
  else if(a==="check")checkUpdate(true);
  else if(a==="retry")loadData(false);
  else if(a==="refreshp")loadData(true);
  else if(a==="adminExit"){leaveAdmin();route();}
  else if(a==="ver"){const n=Date.now();if(n-VT>3000)VTAPS=0;VT=n;VTAPS++;if(VTAPS>=5){VTAPS=0;if(!ADMIN.on)enterAdmin();}}
  else if(a==="diag")diagnose();
  else if(a==="nmcancel"){closeModal();leaveAdmin();route();}
  else if(a==="addpkg")needEdit(function(){openForm(null);});
  else if(a==="edit"){const o=getById(el.dataset.k);if(o)needEdit(function(){openForm(o);});}
  else if(a==="fsave")submitForm();
  else if(a==="showlog")showLog();
  else if(a==="impcost")$("#costFile").click();
  else if(a==="chname")askName(true);
  else if(a==="nmgo"){const nm=($("#nm").value||"").trim();if(!nm)return;S.name=nm;save();closeModal();route();}
  else if(a==="ex")openExport(el.dataset.scope);
  else if(a==="exgo")runExport(el.dataset.scope);
  else if(a==="updgo"){
    S.lang=v;save();
    if(el.dataset.kind==="app"){if(PENDING){writeCache(PENDING.obj,PENDING.info);PENDING=null;}applyUpdate();return;}
    if(PENDING){applyFresh(PENDING.obj,PENDING.info,false);PENDING=null;}
    closeModal();applyLang();route();}
});
document.addEventListener("change",function(e){
  const el=e.target,d=el.dataset||{};
  if(el.id==="impFile"&&el.files[0])importBackup(el.files[0]);
  if(el.id==="costFile"&&el.files[0])importCosts(el.files[0]);
  if(d.act==="fsort"){VS[d.p+"sort"]=el.value;rerender(d.p);}
  if(d.act==="fctry"){VS[d.p+"ctry"]=el.value;rerender(d.p);}
  if(d.act==="cco"){VS.cc=el.value;route();}
  if(el.id==="ssort"){VS.ssort=el.value;$("#slist").innerHTML=searchList();}
  if(el.id==="htol"){VS.htol=el.value;$("#hbody").innerHTML=homeBody();}
  if(el.id==="ptol"){VS.tol=el.value;$("#pres").innerHTML=priceResults();}
});
document.addEventListener("input",function(e){
  const id=e.target.id;
  if(id==="sq"){VS.sq=e.target.value;$("#slist").innerHTML=searchList();}
  if(id==="smax"){VS.smax=e.target.value;$("#slist").innerHTML=searchList();}
  if(id==="hpv"){VS.hv=e.target.value;$("#hbody").innerHTML=homeBody();}
  if(id==="pv"){VS.pv=e.target.value;$("#pres").innerHTML=priceResults();}
});

/* ---------- start ---------- */
applyTheme();applyLang();
loadData(false);
let HIDDEN_AT=0;
document.addEventListener("visibilitychange",function(){
  if(document.hidden){HIDDEN_AT=Date.now();}
  else if(ADMIN.on&&HIDDEN_AT&&Date.now()-HIDDEN_AT>5*60*1000){leaveAdmin();route();}
});
window.addEventListener("load",function(){
  if("serviceWorker"in navigator&&/^https?:/.test(location.protocol)){navigator.serviceWorker.register("sw.js?v="+APP_VERSION).catch(function(){});}
  setTimeout(function(){checkUpdate(false);},2500);
});
